buck_converter.script:
% Configuração do Conversor Buck via Padrão MCP (Simulink.SimulationInput)
modelName = 'Buck_DCDC_Model';
new_system(modelName);

% 1. Parâmetros de Simulação e Isolamento de Workspace
simIn = Simulink.SimulationInput(modelName);
simIn = simIn.setVariable('Vin', 400.0);
simIn = simIn.setVariable('Vout_Target', 48.0);
simIn = simIn.setVariable('DutyCycle', 0.12); % D = 48/400
simIn = simIn.setVariable('Inductor_L', 250e-6);
simIn = simIn.setVariable('Capacitor_C', 470e-6);

simIn = simIn.setModelParameter('StopTime', '0.05');
simIn = simIn.setModelParameter('SaveFormat', 'Dataset');

disp('[MarleyOS] Parâmetros do conversor Buck carregados no SimulationInput.');

boost_converter.script:
% Configuração do Conversor Boost via Padrão MCP
modelName = 'Boost_DCDC_Model';
new_system(modelName);
simIn = Simulink.SimulationInput(modelName);
simIn = simIn.setVariable('Vin', 200.0);
simIn = simIn.setVariable('DutyCycle', 0.50); % Vout = 200 / (1 - 0.5) = 400V
simIn = simIn.setModelParameter('SaveFormat', 'Dataset');

sum_system.script:
% Montagem de Bloco Somador
modelName = 'Sum_Model';
new_system(modelName);
add_block('simulink/Math Operations/Sum', [modelName '/Sum'], 'Inputs', '+-');
simIn = Simulink.SimulationInput(modelName);
simIn = simIn.setModelParameter('SaveFormat', 'Dataset');
